/**
 * Domain types shared by the Firestore data layer, Server Actions and UI.
 *
 * These used to be generated by Prisma. Keeping them hand-written means the
 * application no longer depends on a database-specific code generator, and the
 * enums below remain usable as values (`Role.ADMIN`) exactly like before.
 */

export const Role = {
  EMPLOYEE: "EMPLOYEE",
  INTERN: "INTERN",
  ADMIN: "ADMIN",
  SUPER_ADMIN: "SUPER_ADMIN",
} as const;

export type Role = (typeof Role)[keyof typeof Role];

export const AttendanceStatus = {
  PRESENT: "PRESENT",
  LATE: "LATE",
  ABSENT: "ABSENT",
  INCOMPLETE: "INCOMPLETE",
  LEAVE: "LEAVE",
  HOLIDAY: "HOLIDAY",
} as const;

export type AttendanceStatus = (typeof AttendanceStatus)[keyof typeof AttendanceStatus];

export const AuditAction = {
  EMPLOYEE_CREATED: "EMPLOYEE_CREATED",
  EMPLOYEE_UPDATED: "EMPLOYEE_UPDATED",
  EMPLOYEE_DEACTIVATED: "EMPLOYEE_DEACTIVATED",
  EMPLOYEE_REACTIVATED: "EMPLOYEE_REACTIVATED",
  EMPLOYEE_DELETED: "EMPLOYEE_DELETED",
  EMPLOYEE_ROLE_CHANGED: "EMPLOYEE_ROLE_CHANGED",
  EMPLOYEE_PASSWORD_RESET: "EMPLOYEE_PASSWORD_RESET",
  SCHEDULE_CREATED: "SCHEDULE_CREATED",
  SCHEDULE_UPDATED: "SCHEDULE_UPDATED",
  SCHEDULE_DELETED: "SCHEDULE_DELETED",
  ATTENDANCE_ADJUSTED: "ATTENDANCE_ADJUSTED",
  SETTINGS_UPDATED: "SETTINGS_UPDATED",
  LOCATION_CREATED: "LOCATION_CREATED",
  LOCATION_UPDATED: "LOCATION_UPDATED",
  LOCATION_DELETED: "LOCATION_DELETED",
} as const;

export type AuditAction = (typeof AuditAction)[keyof typeof AuditAction];

export function isRole(value: unknown): value is Role {
  return typeof value === "string" && Object.values(Role).includes(value as Role);
}

export function isAttendanceStatus(value: unknown): value is AttendanceStatus {
  return (
    typeof value === "string" &&
    Object.values(AttendanceStatus).includes(value as AttendanceStatus)
  );
}

export function isAuditAction(value: unknown): value is AuditAction {
  return typeof value === "string" && Object.values(AuditAction).includes(value as AuditAction);
}

export interface User {
  id: string;
  email: string;
  passwordHash: string;
  name: string;
  employeeCode: string | null;
  role: Role;
  department: string | null;
  phone: string | null;
  isActive: boolean;
  scheduleId: string | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface WorkSchedule {
  id: string;
  name: string;
  description: string | null;
  startTime: string;
  endTime: string;
  lateToleranceMinutes: number;
  breakMinutes: number;
  /**
   * Days of the week this schedule applies to, `0 = Minggu` … `6 = Sabtu`.
   *
   * Stored on the schedule rather than in the global settings so a shift can
   * cover Saturday while another stays Monday–Friday. An empty list would make
   * the schedule unusable, so the mapper falls back to Monday–Friday for
   * documents written before this field existed.
   */
  workingDays: number[];
  isActive: boolean;
  isOrganizationDefault: boolean;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Per-day overrides for a schedule.
 *
 * Not used by the Firestore data layer — the application stores a flat list of
 * working days on the schedule itself — but kept because the shape is the
 * natural extension point if a schedule ever needs different hours on
 * Saturday than on Monday.
 */
export interface WorkScheduleDay {
  id: string;
  scheduleId: string;
  dayOfWeek: number;
  startTime: string;
  endTime: string;
  lateToleranceMinutes: number;
  isWorkingDay: boolean;
}

/**
 * One record per employee per calendar day.
 *
 * `workDate` is a `YYYY-MM-DD` key rather than a timestamp: Firestore has no
 * date-only type, and a string keeps the "same day" identity independent of the
 * server timezone. The document id is `${userId}_${workDate}`, which is what
 * makes a duplicate check-in impossible without a transaction.
 */
export interface Attendance {
  id: string;
  userId: string;
  workDate: string;
  checkInAt: Date | null;
  checkOutAt: Date | null;
  checkInLatitude: number | null;
  checkInLongitude: number | null;
  checkInDistanceM: number | null;
  checkOutLatitude: number | null;
  checkOutLongitude: number | null;
  checkOutDistanceM: number | null;
  status: AttendanceStatus;
  lateMinutes: number;
  workedMinutes: number;
  outsideRadius: boolean;
  notes: string | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface WorkLocation {
  id: string;
  name: string;
  address: string | null;
  latitude: number;
  longitude: number;
  radiusMeters: number;
  isActive: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface Setting {
  id: string;
  organizationName: string;
  timezone: string;
  defaultScheduleId: string | null;
  requireLocationValidation: boolean;
  updatedAt: Date;
}

export interface AuditLog {
  id: string;
  actorId: string | null;
  actorName: string | null;
  actorEmail: string | null;
  action: AuditAction;
  entityType: string;
  entityId: string | null;
  summary: string;
  metadata: Record<string, unknown> | null;
  ipAddress: string | null;
  createdAt: Date;
}
